import unittest

from text import slugify


class TestSlugify(unittest.TestCase):
    def test_lowercases_and_joins_words(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_keeps_digits(self):
        self.assertEqual(slugify("Top 10 Songs"), "top-10-songs")

    def test_collapses_runs_of_separators(self):
        self.assertEqual(slugify("a -- b__c"), "a-b-c")

    def test_trims_leading_and_trailing_separators(self):
        self.assertEqual(slugify("  !Hello, World!  "), "hello-world")

    def test_folds_accents_to_ascii(self):
        self.assertEqual(slugify("Café Münster"), "cafe-munster")

    def test_drops_unmappable_characters(self):
        self.assertEqual(slugify("Hello 世界 World"), "hello-world")

    def test_empty_string(self):
        self.assertEqual(slugify(""), "")

    def test_all_separators_gives_empty_string(self):
        self.assertEqual(slugify("!!! ---"), "")

    def test_already_a_slug_is_unchanged(self):
        self.assertEqual(slugify("hello-world"), "hello-world")


if __name__ == "__main__":
    unittest.main()
EOF
